from ccxt.phemex import phemex
from ccxt.abstract.ob_phemex import ImplicitAPI
from ccxt.base.types import Any, Market, Num, Order, OrderSide, OrderType, Str
from typing import List


class ob_phemex(phemex, ImplicitAPI):

    def describe(self) -> Any:
        return self.deep_extend(super(ob_phemex, self).describe(), {
            'id': 'ob_phemex',
            'name': 'Phemex',
            'certified': False,
            'urls': {
            },
            'has': {
                'CORS': None,
                'spot': True,
                'margin': False,
                'swap': True,
                'future': False,
                'option': False,
                'fetchPermissions': True,
                'getOrdersBrokerParameters': True,
            },
            'options': {
                'brokerId': 'Octobot',
                'octobot': {
                    'supportedElements': {
                        'spot': {
                            'orders': ['market', 'limit'],
                            'bundled_orders': {},
                        },
                        'futures': {
                            'orders': ['market', 'limit'],
                            'bundled_orders': {},
                        },
                    },
                    'fixMarketStatus': True,
                    'hasBroker': True,
                    'myTradesFetchUseCcxtPaginate': True,
                },
            },
        })

    def create_order(self, symbol: str, type: OrderType, side: OrderSide, amount: float, price: Num = None, params={}) -> Order:
        # Spot Market orders: passing price switches base implementation to qtyType ByQuote and builds cost via amount × price
        # clear price here so qty stays ByBase(OctoBot phemex_exchange.py create_order parity).
        self.load_markets()
        market = self.market(symbol)
        usePrice = price
        capType = self.capitalize(type)
        if market['spot'] and capType == 'Market':
            usePrice = None
        return super(ob_phemex, self).create_order(symbol, type, side, amount, usePrice, params)

    def cancel_order(self, id: str, symbol: Str = None, params={}) -> Order:
        # Cancel response may expose unified status canceling; those orders cannot be fetched reliably on Phemex.
        # Coerce to canceled — same intent PENDING_CANCEL -> CANCELED.
        order = super(ob_phemex, self).cancel_order(id, symbol, params)
        st = self.safe_string_lower(order, 'status')
        if st == 'canceling':
            order['status'] = 'canceled'
        return order

    def fetch_permissions(self, params={}) -> List[str]:
        self.fetch_balance(params)
        return ['reading', 'spotTrading', 'futuresTrading', 'marginTrading']

    def get_orders_broker_parameters(self, params={}) -> Any:
        return self.extend({}, params)

    def parse_order(self, order: dict, market: Market = None) -> Order:
        # override the standard parseOrder to apply OctoBot's PhemexCCXTAdapter.fix_order:
        # 1) when phemex omits fee.currency, fall back to info.feeCurrency
        # 2) for closed orders, phemex returns base_amount which becomes "amount"; the actual filled
        #    amount is amount - remaining(mirrors the Python that converts base_amount -> filled)
        parsed = super(ob_phemex, self).parse_order(order, market)
        status = self.safe_string_lower(parsed, 'status')
        if status == 'closed':
            info = self.safe_dict(parsed, 'info', {})
            fee = self.safe_dict(parsed, 'fee')
            if fee is not None and self.safe_string(fee, 'currency') is None:
                feeCurrency = self.safe_string(info, 'feeCurrency')
                if feeCurrency is not None:
                    fee['currency'] = feeCurrency
                    parsed['fee'] = fee
            amount = self.safe_number(parsed, 'amount')
            remaining = self.safe_number(parsed, 'remaining')
            if amount is not None and remaining is not None:
                # base_amount is converted to amount by ccxt: real filled amount is amount - remaining
                parsed['amount'] = amount - remaining
        return parsed
